@[category research open, AMS 5]
theorem erdos_195 :
    answer(sorry) = sSup {k : ℕ | ∀ f : ℤ ≃ ℤ, HasMonotoneAP f k}

@[category research open, AMS 11]
theorem erdos_261.parts.iii : answer(sorry) ↔ ∃ x : ℚ,
    𝔠 ≤ #{a : ℕ → ℕ | Erdos261InfiniteRepresentation x a}

@[category research open, AMS 11]
theorem erdos_261.variants.two_representations : answer(sorry) ↔ ∃ x : ℚ,
    2 ≤ #{a : ℕ → ℕ | Erdos261InfiniteRepresentation x a}

@[category research open, AMS 5 11]
theorem erdos_273 : answer(sorry) ↔ ∃ c : StrictCoveringSystem ℤ, ∀ i, ∃ (p : ℕ), p.Prime ∧ 5 ≤ p ∧
    c.moduli i = Ideal.span {↑(p - 1)}

@[category research open, AMS 11]
theorem erdos_288.variants.i2_card_eq_1 : answer(sorry) ↔ Set.Finite { (I, n₂) : (ℕ+ × ℕ+) × ℕ+ |
    I.1 ≤ I.2 ∧ ∃ n : ℕ+, ∑ n₁ ∈ Set.Icc I.1 I.2, (n₁⁻¹ : ℚ) + (n₂⁻¹ : ℚ) = n }

@[category research open, AMS 11]
theorem erdos_313.variants.primary_pseudoperfect_are_infinite :
    Set.Infinite {n | IsPrimaryPseudoperfect n}

@[category research open, AMS 11]
theorem erdos_373.variants.suranyi :
    {(n, a, b) : ℕ × ℕ × ℕ | n ! = a ! * b ! ∧ 1 < n ∧ 1 < a ∧ 1 < b ∧ b ≤ a ∧ a + 1 ≠ n}
      = {(10, 7, 6)}

@[category research open, AMS 11]
theorem erdos_727 : answer(sorry) ↔ ∀ k ≥ 2,
    Set.Infinite {n : ℕ | (Nat.factorial (n + k)) ^ 2 ∣ Nat.factorial (2 * n)}

@[category research open, AMS 5]
theorem erdos_757 {A : Set ℝ} :
    answer(sorry) = sSup {c | IsAdmissible c}

@[category research open, AMS 11]
theorem erdos_1059 :
    answer(sorry) ↔ Set.Infinite {p | p.Prime ∧ AllFactorialSubtractionsComposite p}

@[category research open, AMS 11]
theorem erdos_1065.parts.i :
    answer(sorry) ↔ Set.Infinite {p | ∃ q k, p.Prime ∧ q.Prime ∧ p = 2^k * q + 1}

@[category research open, AMS 11]
theorem erdos_1065.parts.ii : answer(sorry) ↔
    Set.Infinite {p | ∃ q k l, p.Prime ∧ q.Prime ∧ p = 2^k * 3^l * q + 1}

@[category research open, AMS 11]
theorem erdos_1074.parts.iv :
    PillaiPrimes.HasDensity answer(sorry) {p | p.Prime}

@[category research open, AMS 11]
theorem erdos_1108.parts.i : answer(sorry) ↔ ∀ k ≥ 2,
    Set.Finite { a | a ∈ FactorialSums ∧ ∃ m : ℕ, m ^ k = a }

@[category research open, AMS 11]
theorem erdos_1142 :
    answer(sorry) ↔ Infinite { n | Erdos1142Prop n }

@[category research open, AMS 11]
theorem erdos_1146 :
    answer(sorry) ↔ IsEssentialComponent { k | ∃ m n : ℕ, k = 2 ^ m * 3 ^ n }
